import { useEffect, useState } from "react";
import { API } from "../api/api";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";

export default function PollListPage() {
  const [polls, setPolls] = useState([]);
  const [category, setCategory] = useState("all");
  const [visible, setVisible] = useState(5);
  const nav = useNavigate();

  useEffect(() => {
    API.get("/polls").then(res => setPolls(res.data));
  }, []);

  const filtered = polls.filter(p =>
    category === "all" || (p.type || "").toLowerCase() === category
  );

  return (
    <>
      <Navbar />

      <div style={{ padding: "30px", color: "white" }}>

        <h2>Polls 📊</h2>

        {/* CATEGORY FILTER */}
        <div style={{ marginBottom: 20 }}>
          {["all", "student", "teacher", "general"].map(c => (
            <button
              key={c}
              onClick={() => setCategory(c)}
              style={{
                margin: 5,
                padding: 8,
                background: category === c ? "#3b82f6" : "#1f2937",
                color: "white",
                border: "none",
                borderRadius: 10
              }}
            >
              {c}
            </button>
          ))}
        </div>

        {/* POLLS */}
        {filtered.slice(0, visible).map(p => (
          <div
            key={p._id}
            onClick={() => nav(`/poll/${p._id}`)}
            style={{
              padding: 12,
              margin: 10,
              background: "#1f2937",
              borderRadius: 10,
              cursor: "pointer"
            }}
          >
            {p.question}
          </div>
        ))}

        {/* LOAD MORE */}
        {visible < filtered.length && (
          <button
            onClick={() => setVisible(v => v + 5)}
            style={{
              marginTop: 20,
              padding: 10,
              background: "#22c55e",
              border: "none",
              borderRadius: 10
            }}
          >
            Load More
          </button>
        )}

      </div>
    </>
  );
}
